<?php
declare(strict_types=1);
require_once __DIR__ . '/_helper.php';
pengguna_require_admin();
$roles=pengguna_roles();$id=max(0,(int)($_GET['id']??0));
$st=$pdo->prepare('SELECT * FROM users WHERE id=? LIMIT 1');$st->execute([$id]);$user=$st->fetch();if(!$user)exit('Pengguna tidak ditemukan.');
$guruRows=$pdo->query("SELECT g.id,g.nama,g.nip FROM guru g WHERE g.status='aktif' AND (NOT EXISTS(SELECT 1 FROM users u WHERE u.guru_id=g.id) OR EXISTS(SELECT 1 FROM users u WHERE u.guru_id=g.id AND u.id=".$id.")) ORDER BY g.nama")->fetchAll();
$siswaRows=$pdo->query("SELECT s.id,s.nama,s.nis,s.nisn,mk.nama AS kelas FROM siswa s LEFT JOIN siswa_kelas sk ON sk.id=(SELECT sk2.id FROM siswa_kelas sk2 WHERE sk2.siswa_id=s.id AND sk2.tahun_pelajaran_id=(SELECT id FROM tahun_pelajaran WHERE aktif=1 ORDER BY id DESC LIMIT 1) AND sk2.status='aktif' ORDER BY sk2.id DESC LIMIT 1) LEFT JOIN master_kelas mk ON mk.id=sk.kelas_id WHERE s.status='aktif' AND (NOT EXISTS(SELECT 1 FROM users u WHERE u.siswa_id=s.id) OR EXISTS(SELECT 1 FROM users u WHERE u.siswa_id=s.id AND u.id=".$id.")) ORDER BY s.nama")->fetchAll();
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 require_valid_csrf();$username=trim((string)($_POST['username']??''));$nama=trim((string)($_POST['nama']??''));$role=(string)($_POST['role']??'');$guruId=max(0,(int)($_POST['guru_id']??0));$siswaId=max(0,(int)($_POST['siswa_id']??0));$password=(string)($_POST['password']??'');$password2=(string)($_POST['password2']??'');
 if($username===''||$nama===''||!isset($roles[$role]))$error='Username, nama, dan role wajib diisi dengan benar.';elseif(in_array($role,['guru','guru_bk'],true)&&$guruId<=0)$error='Akun Guru/Guru BK wajib terhubung ke data Guru.';elseif($role==='siswa'&&$siswaId<=0)$error='Akun Siswa wajib terhubung ke data Siswa.';elseif(!in_array($role,['guru','guru_bk'],true)&&$guruId>0)$error='Relasi Guru hanya boleh untuk role Guru atau Guru BK.';elseif($role!=='siswa'&&$siswaId>0)$error='Relasi Siswa hanya boleh untuk role Siswa.';elseif($password!==''&&strlen($password)<8)$error='Password minimal 8 karakter.';elseif($password!==''&&$password!==$password2)$error='Konfirmasi password tidak sama.';
 if($error==='')try{
  $st=$pdo->prepare('SELECT id FROM users WHERE username=? AND id<>? LIMIT 1');$st->execute([$username,$id]);if($st->fetch())$error='Username sudah digunakan.';
  if($error===''){
   if($guruId>0){$st=$pdo->prepare('SELECT id FROM users WHERE guru_id=? AND id<>? LIMIT 1');$st->execute([$guruId,$id]);if($st->fetch())$error='Guru tersebut sudah memiliki akun lain.';}
   if($siswaId>0){$st=$pdo->prepare('SELECT id FROM users WHERE siswa_id=? AND id<>? LIMIT 1');$st->execute([$siswaId,$id]);if($st->fetch())$error='Siswa tersebut sudah memiliki akun lain.';}
  }
  if($error===''){$pdo->beginTransaction();if($password!==''){$st=$pdo->prepare('UPDATE users SET username=?,nama=?,role=?,guru_id=?,siswa_id=?,password=? WHERE id=?');$st->execute([$username,$nama,$role,$guruId?:null,$siswaId?:null,password_hash($password,PASSWORD_DEFAULT),$id]);}else{$st=$pdo->prepare('UPDATE users SET username=?,nama=?,role=?,guru_id=?,siswa_id=? WHERE id=?');$st->execute([$username,$nama,$role,$guruId?:null,$siswaId?:null,$id]);}pengguna_audit('UPDATE_USER',$id,'Mengubah akun '.$username.' dengan role '.$role);$pdo->commit();pengguna_flash('Pengguna berhasil diperbarui.');redirect('pengguna/index.php');}
 }catch(PDOException $e){if($pdo->inTransaction())$pdo->rollBack();$error='Gagal memperbarui pengguna.';}
}
$page_title='Edit Pengguna';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';
?><main class="main"><header class="topbar"><div class="topbar-title">Edit Pengguna</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content"><div class="page-header"><div><h1>Edit Pengguna</h1><p>Perubahan akun dicatat ke audit log.</p></div><div class="page-header-actions"><a class="btn btn-secondary" href="<?=BASE_URL?>pengguna/index.php"><i class="bi bi-arrow-left"></i> Kembali</a></div></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="form-card"><form method="post"><?=csrf_field()?><div class="form-grid"><label>Username<input class="form-control" name="username" value="<?=e($user['username'])?>" required autocomplete="username"></label><label>Nama Pengguna<input class="form-control" name="nama" value="<?=e($user['nama'])?>" required></label><label>Role<select class="form-control" name="role" id="role" required><?php foreach($roles as $k=>$v):?><option value="<?=$k?>" <?=$user['role']===$k?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></label><label>Password Baru<input class="form-control" type="password" name="password" minlength="8" autocomplete="new-password"><small>Kosongkan jika tidak ingin mengubah password.</small></label><label>Konfirmasi Password<input class="form-control" type="password" name="password2" minlength="8" autocomplete="new-password"></label><label id="guruWrap">Hubungkan Guru<select class="form-control" name="guru_id"><option value="0">Tidak terhubung</option><?php foreach($guruRows as $r):?><option value="<?=$r['id']?>" <?=((int)$user['guru_id']===(int)$r['id'])?'selected':''?>><?=e($r['nama'])?><?= $r['nip']?' · '.e($r['nip']):''?></option><?php endforeach;?></select></label><div id="siswaWrap" class="form-group-full">
<label>Hubungkan Siswa</label>
<div class="student-picker" data-student-picker data-items="<?=e(json_encode($siswaRows,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES))?>">
<input type="hidden" name="siswa_id" data-student-value value="<?=e((string)((int)$user['siswa_id']))?>">
<div class="student-picker-toolbar"><select class="form-control" data-student-class><option value="">Pilih Kelas Terlebih Dahulu</option></select><input class="form-control" type="search" data-student-search placeholder="Pilih kelas terlebih dahulu, lalu cari nama/NIS/NISN..." autocomplete="off"></div>
<div data-student-selected></div><div class="student-picker-results" data-student-results></div><div class="student-picker-empty" data-student-empty hidden>Tidak ada siswa yang sesuai.</div>
<small class="student-picker-help"><i class="bi bi-funnel"></i> Pilih kelas terlebih dahulu, kemudian pilih siswa.</small>
</div></div></div><div class="form-actions"><button class="btn btn-primary" type="submit"><i class="bi bi-save"></i> Simpan Perubahan</button><a class="btn btn-secondary" href="<?=BASE_URL?>pengguna/index.php">Batal</a></div></form></div></section></main><script>const r=document.getElementById('role'),g=document.getElementById('guruWrap'),s=document.getElementById('siswaWrap');function sync(){g.style.display=(r.value==='guru'||r.value==='guru_bk')?'flex':'none';s.style.display=r.value==='siswa'?'flex':'none'}r.addEventListener('change',sync);sync();</script><?php require_once __DIR__.'/../layouts/footer.php'; ?>
